contracts/AttestationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AttestationRegistry
 * @dev Stores verification attestation claims (IDENTITY_VERIFIED, OWNERSHIP_VERIFIED,
 *      PROFESSIONALLY_INSPECTED, MANUFACTURER_VERIFIED) anchored on MST blockchain.
 */
contract AttestationRegistry {
    struct Attestation {
        string passportId;
        string claim;
        bytes32 evidenceHash;
        address issuer;
        uint256 timestamp;
    }

    mapping(string => Attestation[]) private attestations;

    event AttestationAdded(
        string indexed passportId,
        string claim,
        bytes32 evidenceHash,
        address indexed issuer,
        uint256 timestamp
    );

    /**
     * @dev Add a verification attestation for a passport.
     * @param _passportId The passport to attest
     * @param _claim Claim type (e.g. "IDENTITY_VERIFIED")
     * @param _evidenceHash Hash of evidence document supporting the claim
     */
    function addAttestation(
        string calldata _passportId,
        string calldata _claim,
        bytes32 _evidenceHash
    ) external {
        attestations[_passportId].push(Attestation({
            passportId: _passportId,
            claim: _claim,
            evidenceHash: _evidenceHash,
            issuer: msg.sender,
            timestamp: block.timestamp
        }));

        emit AttestationAdded(
            _passportId,
            _claim,
            _evidenceHash,
            msg.sender,
            block.timestamp
        );
    }

    /**
     * @dev Get number of attestations for a passport.
     */
    function getAttestationCount(string calldata _passportId)
        external
        view
        returns (uint256)
    {
        return attestations[_passportId].length;
    }

    /**
     * @dev Get a specific attestation by index.
     */
    function getAttestation(string calldata _passportId, uint256 _index)
        external
        view
        returns (
            string memory claim,
            bytes32 evidenceHash,
            address issuer,
            uint256 timestamp
        )
    {
        require(_index < attestations[_passportId].length, "Index out of bounds");
        Attestation storage a = attestations[_passportId][_index];
        return (a.claim, a.evidenceHash, a.issuer, a.timestamp);
    }
}

contracts/LifecycleRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title LifecycleRegistry
 * @dev Immutable historical record of all lifecycle events for a product passport.
 *      Events include: PURCHASED, INSPECTED, SERVICED, LISTED, SOLD,
 *      TRANSFERRED, DISPUTED, FLAGGED, STOLEN, RECOVERED, RETIRED.
 */
contract LifecycleRegistry {
    struct LifecycleEvent {
        string passportId;
        string eventType;
        bytes32 payloadHash;
        address actor;
        uint256 timestamp;
    }

    mapping(string => LifecycleEvent[]) private lifecycleEvents;

    event LifecycleEventLogged(
        string indexed passportId,
        string eventType,
        bytes32 payloadHash,
        address indexed actor,
        uint256 timestamp
    );

    /**
     * @dev Log an immutable lifecycle event.
     * @param _passportId The passport this event belongs to
     * @param _eventType Type of lifecycle event (e.g. "PURCHASED", "TRANSFERRED")
     * @param _payloadHash Hash of the event payload/details
     */
    function logEvent(
        string calldata _passportId,
        string calldata _eventType,
        bytes32 _payloadHash
    ) external {
        lifecycleEvents[_passportId].push(LifecycleEvent({
            passportId: _passportId,
            eventType: _eventType,
            payloadHash: _payloadHash,
            actor: msg.sender,
            timestamp: block.timestamp
        }));

        emit LifecycleEventLogged(
            _passportId,
            _eventType,
            _payloadHash,
            msg.sender,
            block.timestamp
        );
    }

    /**
     * @dev Get number of lifecycle events for a passport.
     */
    function getEventCount(string calldata _passportId)
        external
        view
        returns (uint256)
    {
        return lifecycleEvents[_passportId].length;
    }

    /**
     * @dev Get a specific lifecycle event by index.
     */
    function getEvent(string calldata _passportId, uint256 _index)
        external
        view
        returns (
            string memory eventType,
            bytes32 payloadHash,
            address actor,
            uint256 timestamp
        )
    {
        require(_index < lifecycleEvents[_passportId].length, "Index out of bounds");
        LifecycleEvent storage e = lifecycleEvents[_passportId][_index];
        return (e.eventType, e.payloadHash, e.actor, e.timestamp);
    }
}

contracts/OwnershipRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title OwnershipRegistry
 * @dev Manages verifiable ownership transfers with dual-confirmation escrow.
 *      The passport ID persists while ownership changes hands.
 */
contract OwnershipRegistry {
    enum TransferStatus { NONE, INITIATED, COMPLETED }

    struct OwnerRecord {
        address owner;
        uint256 acquiredAt;
        bytes32 transferTxRef;
    }

    struct PendingTransfer {
        string passportId;
        address seller;
        address buyer;
        TransferStatus status;
        uint256 initiatedAt;
    }

    mapping(string => OwnerRecord) private currentOwners;
    mapping(string => PendingTransfer) private pendingTransfers;

    event OwnershipRegistered(string indexed passportId, address indexed owner, uint256 timestamp);
    event TransferInitiated(string indexed passportId, address indexed seller, address indexed buyer, uint256 timestamp);
    event TransferCompleted(string indexed passportId, address indexed newOwner, uint256 timestamp);

    /**
     * @dev Register initial ownership when creating a passport.
     */
    function registerOwnership(string calldata _passportId) external {
        require(currentOwners[_passportId].owner == address(0), "Ownership already registered");

        currentOwners[_passportId] = OwnerRecord({
            owner: msg.sender,
            acquiredAt: block.timestamp,
            transferTxRef: bytes32(0)
        });

        emit OwnershipRegistered(_passportId, msg.sender, block.timestamp);
    }

    /**
     * @dev Initiate a transfer (called by seller). Buyer address must be known.
     */
    function initiateTransfer(
        string calldata _passportId,
        address _buyer
    ) external {
        require(currentOwners[_passportId].owner == msg.sender, "Not the owner");
        require(_buyer != address(0), "Invalid buyer address");
        require(
            pendingTransfers[_passportId].status != TransferStatus.INITIATED,
            "Transfer already pending"
        );

        pendingTransfers[_passportId] = PendingTransfer({
            passportId: _passportId,
            seller: msg.sender,
            buyer: _buyer,
            status: TransferStatus.INITIATED,
            initiatedAt: block.timestamp
        });

        emit TransferInitiated(_passportId, msg.sender, _buyer, block.timestamp);
    }

    /**
     * @dev Complete the transfer (called by buyer to confirm handover).
     */
    function completeTransfer(string calldata _passportId) external {
        PendingTransfer storage pt = pendingTransfers[_passportId];
        require(pt.status == TransferStatus.INITIATED, "No pending transfer");
        require(pt.buyer == msg.sender, "Not the designated buyer");

        currentOwners[_passportId] = OwnerRecord({
            owner: msg.sender,
            acquiredAt: block.timestamp,
            transferTxRef: keccak256(abi.encodePacked(_passportId, pt.seller, msg.sender, block.timestamp))
        });

        pt.status = TransferStatus.COMPLETED;

        emit TransferCompleted(_passportId, msg.sender, block.timestamp);
    }

    /**
     * @dev Get current owner of a passport.
     */
    function getOwner(string calldata _passportId)
        external
        view
        returns (address owner, uint256 acquiredAt)
    {
        OwnerRecord storage r = currentOwners[_passportId];
        return (r.owner, r.acquiredAt);
    }
}

contracts/ProductPassportRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ProductPassportRegistry
 * @dev Registers persistent product passport identities on MST blockchain.
 *      Each product gets a permanent Passport ID that survives ownership changes.
 */
contract ProductPassportRegistry {
    struct Passport {
        string passportId;
        bytes32 identifierHash;
        address registrant;
        uint256 registeredAt;
        bool exists;
    }

    mapping(string => Passport) private passports;
    string[] private passportIds;

    event PassportRegistered(
        string indexed passportId,
        bytes32 identifierHash,
        address indexed registrant,
        uint256 timestamp
    );

    /**
     * @dev Register a new product passport.
     * @param _passportId Unique passport identifier (e.g. "PP-82941")
     * @param _identifierHash Keccak256 hash of the product's physical identifier (serial/IMEI)
     */
    function registerPassport(
        string calldata _passportId,
        bytes32 _identifierHash
    ) external {
        require(!passports[_passportId].exists, "Passport already registered");

        passports[_passportId] = Passport({
            passportId: _passportId,
            identifierHash: _identifierHash,
            registrant: msg.sender,
            registeredAt: block.timestamp,
            exists: true
        });

        passportIds.push(_passportId);

        emit PassportRegistered(
            _passportId,
            _identifierHash,
            msg.sender,
            block.timestamp
        );
    }

    /**
     * @dev Get passport details by ID.
     */
    function getPassport(string calldata _passportId)
        external
        view
        returns (
            bytes32 identifierHash,
            address registrant,
            uint256 registeredAt
        )
    {
        require(passports[_passportId].exists, "Passport not found");
        Passport storage p = passports[_passportId];
        return (p.identifierHash, p.registrant, p.registeredAt);
    }

    /**
     * @dev Check if a passport exists.
     */
    function passportExists(string calldata _passportId)
        external
        view
        returns (bool)
    {
        return passports[_passportId].exists;
    }

    /**
     * @dev Get total number of registered passports.
     */
    function totalPassports() external view returns (uint256) {
        return passportIds.length;
    }
}

contracts/ServiceRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ServiceRegistry
 * @dev Records authorized service center attestations (battery replacements,
 *      repairs, refurbishments) directly onto the product passport.
 */
contract ServiceRegistry {
    struct ServiceRecord {
        string passportId;
        string serviceType;
        bytes32 documentHash;
        address serviceCenter;
        uint256 timestamp;
    }

    mapping(string => ServiceRecord[]) private serviceRecords;

    event ServiceRecorded(
        string indexed passportId,
        string serviceType,
        bytes32 documentHash,
        address indexed serviceCenter,
        uint256 timestamp
    );

    /**
     * @dev Record a verified service event.
     * @param _passportId The passport being serviced
     * @param _serviceType Type of service (e.g. "BATTERY_REPLACEMENT")
     * @param _documentHash Hash of the service documentation
     */
    function recordService(
        string calldata _passportId,
        string calldata _serviceType,
        bytes32 _documentHash
    ) external {
        serviceRecords[_passportId].push(ServiceRecord({
            passportId: _passportId,
            serviceType: _serviceType,
            documentHash: _documentHash,
            serviceCenter: msg.sender,
            timestamp: block.timestamp
        }));

        emit ServiceRecorded(
            _passportId,
            _serviceType,
            _documentHash,
            msg.sender,
            block.timestamp
        );
    }

    /**
     * @dev Get number of service records for a passport.
     */
    function getServiceCount(string calldata _passportId)
        external
        view
        returns (uint256)
    {
        return serviceRecords[_passportId].length;
    }

    /**
     * @dev Get a specific service record by index.
     */
    function getServiceRecord(string calldata _passportId, uint256 _index)
        external
        view
        returns (
            string memory serviceType,
            bytes32 documentHash,
            address serviceCenter,
            uint256 timestamp
        )
    {
        require(_index < serviceRecords[_passportId].length, "Index out of bounds");
        ServiceRecord storage s = serviceRecords[_passportId][_index];
        return (s.serviceType, s.documentHash, s.serviceCenter, s.timestamp);
    }
}

